-- CAT_VOIDHUNTERS
IMAGOdb.npcs.CAT_VOIDHUNTERS["alleria_windrunner_tww"].name = "Alleria Windrunner"
IMAGOdb.npcs.CAT_VOIDHUNTERS["alleria_windrunner_tww"].race = "Void Elf (former high elf)"
IMAGOdb.npcs.CAT_VOIDHUNTERS["alleria_windrunner_tww"].lore = [[Known to the people of Azeroth as one of the Alliance's greatest war heroes, Alleria has fought in the Second War and in the millennia-long crusade against the Burning Legion. Now, her singular focus is the Harbinger of the Void, Xal'atath.

With Dalaran destroyed and Archmage Khadgar crippled in the blast, Alleria hunts her quarry across Khaz Algar and beyond. She is infused with the fallen naaru L'ura and wields void power for the good of Azeroth — always on the brink of falling to madness, with constant whispers assaulting her mind. The obsession has become dangerous, but she won't rest until her foe lies defeated.]]
IMAGOdb.npcs.CAT_VOIDHUNTERS["alleria_windrunner_tww"].zones = {"Dornogal", "K'aresh", "Tazavesh, the Veiled Market", "Azj-Kahet", "Hallowfall", "Manaforge Omega", "City of Threads", "Undermine", "Isle of Dorn", "Dalaran", "Khaz Algar"}
IMAGOdb.npcs.CAT_VOIDHUNTERS["alleria_windrunner_tww"].source = "Cadash"
IMAGOdb.npcs.CAT_VOIDHUNTERS["alleria_windrunner_tww"].timeline = IMAGOdb.timelines.ALLERIA_WINDRUNNER

IMAGOdb.npcs.CAT_VOIDHUNTERS["anduin_wrynn_tww"].name = "Anduin Wrynn"
IMAGOdb.npcs.CAT_VOIDHUNTERS["anduin_wrynn_tww"].race = "Human"
IMAGOdb.npcs.CAT_VOIDHUNTERS["anduin_wrynn_tww"].lore = [[The High King-in-absentia of the Alliance feels like a mere shadow of his former radiant self. Deeply traumatized by his time as the Jailer's weapon — forced to slaughter innocents he couldn't protect — Anduin stepped back from politics and from the Light itself, consumed by guilt.

When Xal'atath destroys Dalaran, Thrall tracks Anduin down and convinces him to fight once more. In the depths of Hallowfall, surrounded by the unshakeable faith of the Arathi and the warm light of their star Beledar, Anduin finally finds his way back to himself.]]
IMAGOdb.npcs.CAT_VOIDHUNTERS["anduin_wrynn_tww"].zones = {}
IMAGOdb.npcs.CAT_VOIDHUNTERS["anduin_wrynn_tww"].source = "Cadash"
IMAGOdb.npcs.CAT_VOIDHUNTERS["anduin_wrynn_tww"].timeline = IMAGOdb.timelines.ANDUIN_WRYNN

-- CAT_HARBINGER
IMAGOdb.npcs.CAT_HARBINGER["xal_atath_tww"].name = "Xal'atath"
IMAGOdb.npcs.CAT_HARBINGER["xal_atath_tww"].race = "Unknown"
IMAGOdb.npcs.CAT_HARBINGER["xal_atath_tww"].lore = [[Her smile is a threat, her whispers are warnings, and her promises are lies. Having escaped her imprisonment within the Blade of the Black Empire, the Harbinger of the Void now walks Azeroth freely, and the scope of her grand design is only beginning to come into focus.

Destroying Dalaran was merely the opening move. Xal'atath systematically empowers the Dark Heart with various cosmic energies while endlessly delaying the Champions who pursue her. She dances around Alleria Windrunner's obsessive hunt, never attacking her directly, always one step ahead. Whatever her ultimate goal is — she is terrifyingly close to achieving it.]]
IMAGOdb.npcs.CAT_HARBINGER["xal_atath_tww"].zones = {"K'aresh", "Manaforge Omega", "Tazavesh, the Veiled Market"}
IMAGOdb.npcs.CAT_HARBINGER["xal_atath_tww"].source = "Cadash"
IMAGOdb.npcs.CAT_HARBINGER["xal_atath_tww"].timeline = IMAGOdb.timelines.XAL_ATATH

-- CAT_KIRIN_TOR
IMAGOdb.npcs.CAT_KIRIN_TOR["khadgar_tww"].name = "Archmage Khadgar"
IMAGOdb.npcs.CAT_KIRIN_TOR["khadgar_tww"].race = "Human"
IMAGOdb.npcs.CAT_KIRIN_TOR["khadgar_tww"].lore = [[The Archmage of the Kirin Tor is one of the most powerful human mages to have ever lived, and one of Azeroth's most enduring champions. Khadgar has defeated warlocks, demons, corrupted titans, and Old Gods alike — and through it all, he has never stopped proving that he is not simply the Guardian's apprentice, but a legend in his own right.

When Xal'atath unleashes the Dark Heart upon Dalaran, it is Khadgar who throws himself into the path of the blast. He survives, but loses the use of his legs. His legs may be gone, but his resolve — and his magic — remain perfectly intact.]]
IMAGOdb.npcs.CAT_KIRIN_TOR["khadgar_tww"].zones = {"Isle of Dorn", "Dornogal", "Dalaran", "Hallowfall", "Valdrakken"}
IMAGOdb.npcs.CAT_KIRIN_TOR["khadgar_tww"].source = "Cadash"
IMAGOdb.npcs.CAT_KIRIN_TOR["khadgar_tww"].timeline = IMAGOdb.timelines.KHADGAR

-- CAT_EARTHEN
IMAGOdb.npcs.CAT_EARTHEN["magni_bronzebeard_tww"].name = "Magni Bronzebeard"
IMAGOdb.npcs.CAT_EARTHEN["magni_bronzebeard_tww"].race = "Dwarf"
IMAGOdb.npcs.CAT_EARTHEN["magni_bronzebeard_tww"].lore = [[Once turned to diamond in a ritual to commune with Azeroth's world-soul, Magni Bronzebeard served for years as the planet's Speaker — its voice, its guardian, its champion. He sacrificed his family and his kingship for this duty, and the cost weighed on him more with every passing year.

Now, Azeroth has restored him to flesh. The world no longer needs its Speaker in the same way. And Magni, finally freed from his diamond prison and his overwhelming sense of duty, has a chance to be something he hasn't been in a very long time: a father. A grandfather. A dwarf, plain and simple.]]
IMAGOdb.npcs.CAT_EARTHEN["magni_bronzebeard_tww"].zones = {"Dalaran", "Dornogal", "The Ringing Deeps", "Isle of Dorn", "Tanaris"}
IMAGOdb.npcs.CAT_EARTHEN["magni_bronzebeard_tww"].source = "Cadash"
IMAGOdb.npcs.CAT_EARTHEN["magni_bronzebeard_tww"].timeline = IMAGOdb.timelines.MAGNI_BRONZEBEARD

-- CAT_ARATHI
IMAGOdb.npcs.CAT_ARATHI["faerin_lothar_tww"].name = "Faerin Lothar"
IMAGOdb.npcs.CAT_ARATHI["faerin_lothar_tww"].race = "Human"
IMAGOdb.npcs.CAT_ARATHI["faerin_lothar_tww"].lore = [[This young paladin is a beacon of hope and optimism to her fellow soldiers, always the first to rush into battle, protecting others with her shield and her faith in the Light. Faerin had always had a knack for danger — she snuck aboard the airship of the Arathi expedition to Hallowfall as just a small child. The crash landing cost her an eye and an arm, but also gave her a home and a people.

A descendant of Anduin Lothar, the great Lion of Azeroth, Faerin carries that legendary name into a new age — and carries it well. Her warmth and unshakeable faith proved strong enough to help a fallen High King find his way back to the Light.]]
IMAGOdb.npcs.CAT_ARATHI["faerin_lothar_tww"].zones = {"Dornogal", "Hallowfall", "Azj-Kahet", "Arathi Highlands", "Khaz Algar"}
IMAGOdb.npcs.CAT_ARATHI["faerin_lothar_tww"].source = "Cadash"
IMAGOdb.npcs.CAT_ARATHI["faerin_lothar_tww"].timeline = IMAGOdb.timelines.FAERIN_LOTHAR

-- CAT_HARANIR
IMAGOdb.npcs.CAT_HARANIR["orweyna_tww"].name = "Orweyna"
IMAGOdb.npcs.CAT_HARANIR["orweyna_tww"].race = "Haranir"
IMAGOdb.npcs.CAT_HARANIR["orweyna_tww"].lore = [[A scout of the mysterious and reclusive race called the Haranir, Orweyna is quite different from most of her kind. Fascinated with the world and its people beyond the borders of her homeland, she broke with her people's sacred oaths of secrecy and seclusion to seek help — first making contact with the Champion of Azeroth in the depths of Azj-Kahet.

She has a special connection to her goddess, Aln'hara, receiving visions of impending dangers that mirror the Radiant Song. The threat she has witnessed is unlike anything the Haranir can face alone — and so Orweyna has ventured out into a world she is only beginning to understand, carrying the weight of her people's fate on her shoulders.]]
IMAGOdb.npcs.CAT_HARANIR["orweyna_tww"].zones = {"Azj-Kahet", "Hallowfall", "The Ringing Deeps", "Undermine", "Dornogal"}
IMAGOdb.npcs.CAT_HARANIR["orweyna_tww"].source = "Cadash"
IMAGOdb.npcs.CAT_HARANIR["orweyna_tww"].timeline = IMAGOdb.timelines.ORWEYNA